사용자님이 "아무거나로 정해서 지금 만들어 주세요"라고 하셨으므로, 코드를 직접 출력해서 제공하겠습니다. 복사해서 프로젝트에 저장하시면 됩니다.

## 📦 가계부 앱 완전 구성

### **백엔드 - server.js**

```javascript
import express from 'express';
import sqlite3 from 'sqlite3';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import cors from 'cors';

const app = express();
const PORT = 3001;
const JWT_SECRET = 'household-app-secret-key';

app.use(cors());
app.use(express.json());

const db = new sqlite3.Database('./household.db');

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    amount REAL NOT NULL,
    category TEXT NOT NULL,
    description TEXT,
    date DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
  )`);
});

// 회원가입
app.post('/api/auth/signup', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: '필수 정보 필요' });

  const hashedPassword = bcrypt.hashSync(password, 10);
  db.run('INSERT INTO users (username, password) VALUES (?, ?)', [username, hashedPassword], function (err) {
    if (err) return res.status(400).json({ error: '이미 존재하는 사용자명' });
    const token = jwt.sign({ userId: this.lastID }, JWT_SECRET, { expiresIn: '7d' });
    res.status(201).json({ token, userId: this.lastID, username });
  });
});

// 로그인
app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: '필수 정보 필요' });

  db.get('SELECT * FROM users WHERE username = ?', [username], (err, user) => {
    if (!user || !bcrypt.compareSync(password, user.password)) {
      return res.status(401).json({ error: '로그인 실패' });
    }
    const token = jwt.sign({ userId: user.id }, JWT_SECRET, { expiresIn: '7d' });
    res.json({ token, userId: user.id, username: user.username });
  });
});

// 인증 미들웨어
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];
  if (!token) return res.status(401).json({ error: '토큰 필요' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: '유효하지 않은 토큰' });
    req.user = user;
    next();
  });
};

// 거래 추가
app.post('/api/transactions', authenticateToken, (req, res) => {
  const { type, amount, category, description, date } = req.body;
  const userId = req.user.userId;
  if (!type || !amount || !category) return res.status(400).json({ error: '필수 정보 필요' });

  db.run(
    'INSERT INTO transactions (user_id, type, amount, category, description, date) VALUES (?, ?, ?, ?, ?, ?)',
    [userId, type, amount, category, description, date || new Date().toISOString()],
    function (err) {
      if (err) return res.status(500).json({ error: '추가 실패' });
      res.status(201).json({ id: this.lastID, type, amount, category, description, date });
    }
  );
});

// 거래 조회
app.get('/api/transactions', authenticateToken, (req, res) => {
  db.all('SELECT * FROM transactions WHERE user_id = ? ORDER BY date DESC', [req.user.userId], (err, rows) => {
    if (err) return res.status(500).json({ error: '조회 실패' });
    res.json(rows || []);
  });
});

// 거래 수정
app.put('/api/transactions/:id', authenticateToken, (req, res) => {
  const { type, amount, category, description, date } = req.body;
  db.run(
    'UPDATE transactions SET type = ?, amount = ?, category = ?, description = ?, date = ? WHERE id = ? AND user_id = ?',
    [type, amount, category, description, date, req.params.id, req.user.userId],
    function (err) {
      if (err || this.changes === 0) return res.status(404).json({ error: '실패' });
      res.json({ id: req.params.id, type, amount, category, description, date });
    }
  );
});

// 거래 삭제
app.delete('/api/transactions/:id', authenticateToken, (req, res) => {
  db.run('DELETE FROM transactions WHERE id = ? AND user_id = ?', [req.params.id, req.user.userId], function (err) {
    if (err || this.changes === 0) return res.status(404).json({ error: '실패' });
    res.status(204).send();
  });
});

app.listen(PORT, () => console.log(`서버 실행: http://localhost:${PORT}`));
```

