### **프론트엔드 - src/App.tsx**

```typescript
import { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

const API = axios.create({ baseURL: 'http://localhost:3001/api' });

interface Transaction {
  id: number;
  type: 'income' | 'expense';
  amount: number;
  category: string;
  description: string;
  date: string;
}

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [newTransaction, setNewTransaction] = useState({
    type: 'expense' as const,
    amount: '',
    category: '',
    description: '',
  });

  const token = localStorage.getItem('token');

  useEffect(() => {
    if (token) {
      setIsLoggedIn(true);
      fetchTransactions();
    }
  }, []);

  const fetchTransactions = async () => {
    try {
      const res = await API.get('/transactions', { headers: { Authorization: `Bearer ${token}` } });
      setTransactions(res.data);
    } catch (error) {
      console.error('거래 조회 실패:', error);
    }
  };

  const handleSignup = async () => {
    try {
      const res = await API.post('/auth/signup', { username, password });
      localStorage.setItem('token', res.data.token);
      setIsLoggedIn(true);
      setUsername('');
      setPassword('');
      fetchTransactions();
    } catch (error: any) {
      alert(error.response?.data?.error || '회원가입 실패');
    }
  };

  const handleLogin = async () => {
    try {
      const res = await API.post('/auth/login', { username, password });
      localStorage.setItem('token', res.data.token);
      setIsLoggedIn(true);
      setUsername('');
      setPassword('');
      fetchTransactions();
    } catch (error: any) {
      alert(error.response?.data?.error || '로그인 실패');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setIsLoggedIn(false);
    setTransactions([]);
  };

  const handleAddTransaction = async () => {
    if (!newTransaction.amount || !newTransaction.category) {
      alert('금액과 카테고리를 입력하세요');
      return;
    }

    try {
      await API.post(
        '/transactions',
        {
          ...newTransaction,
          amount: parseFloat(newTransaction.amount),
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setNewTransaction({ type: 'expense', amount: '', category: '', description: '' });
      fetchTransactions();
    } catch (error) {
      alert('거래 추가 실패');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      await API.delete(`/transactions/${id}`, { headers: { Authorization: `Bearer ${token}` } });
      fetchTransactions();
    } catch (error) {
      alert('거래 삭제 실패');
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="auth-container">
        <div className="auth-box">
          <h1>가계부</h1>
          <input placeholder="사용자명" value={username} onChange={(e) => setUsername(e.target.value)} />
          <input
            type="password"
            placeholder="비밀번호"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button onClick={handleLogin}>로그인</button>
          <button onClick={handleSignup}>회원가입</button>
        </div>
      </div>
    );
  }

  const income = transactions.filter((t) => t.type === 'income').reduce((sum, t) => sum + t.amount, 0);
  const expense = transactions.filter((t) => t.type === 'expense').reduce((sum, t) => sum + t.amount, 0);

  return (
    <div className="app">
      <header>
        <h1>가계부</h1>
        <button onClick={handleLogout}>로그아웃</button>
      </header>

      <div className="summary">
        <div className="stat">
          <span>수입</span>
          <span className="income">₩{income.toLocaleString()}</span>
        </div>
        <div className="stat">
          <span>지출</span>
          <span className="expense">₩{expense.toLocaleString()}</span>
        </div>
        <div className="stat">
          <span>순액</span>
          <span className={income - expense >= 0 ? 'income' : 'expense'}>
            ₩{(income - expense).toLocaleString()}
          </span>
        </div>
      </div>

      <div className="add-transaction">
        <h2>거래 추가</h2>
        <div className="form">
          <select value={newTransaction.type} onChange={(e) => setNewTransaction({ ...newTransaction, type: e.target.value as any })}>
            <option value="income">수입</option>
            <option value="expense">지출</option>
          </select>
          <input type="number" placeholder="금액" value={newTransaction.amount} onChange={(e) => setNewTransaction({ ...newTransaction, amount: e.target.value })} />
          <input placeholder="카테고리 (예: 급여, 식사)" value={newTransaction.category} onChange={(e) => setNewTransaction({ ...newTransaction, category: e.target.value })} />
          <input placeholder="설명 (선택사항)" value={newTransaction.description} onChange={(e) => setNewTransaction({ ...newTransaction, description: e.target.value })} />
          <button onClick={handleAddTransaction}>추가</button>
        </div>
      </div>

      <div className="transactions">
        <h2>거래 목록</h2>
        {transactions.length === 0 ? (
          <p className="empty">거래가 없습니다</p>
        ) : (
          <ul>
            {transactions.map((t) => (
              <li key={t.id} className={t.type}>
                <div>
                  <span className="category">{t.category}</span>
                  <span className="description">{t.description}</span>
                </div>
                <div>
                  <span className="amount">
                    {t.type === 'income' ? '+' : '-'}₩{t.amount.toLocaleString()}
                  </span>
                  <button onClick={() => handleDelete(t.id)} className="delete">
                    ✕
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
```

