  margin-bottom: 30px;
}

.add-transaction h2 {
  margin-bottom: 15px;
  color: #333;
}

.form {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr auto;
  gap: 10px;
}

.form select,
.form input {
  padding: 10px;
  border: 1px solid #ddd;
  border-radius: 6px;
  font-size: 14px;
}

.form button {
  padding: 10px 20px;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-weight: bold;
}

.transactions {
  background: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.transactions h2 {
  margin-bottom: 15px;
  color: #333;
}

.transactions ul {
  list-style: none;
}

.transactions li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  border-bottom: 1px solid #eee;
}

.transactions li:last-child {
  border-bottom: none;
}

.category {
  font-weight: bold;
  color: #667eea;
  display: block;
}

.description {
  font-size: 12px;
  color: #999;
  display: block;
}

.amount {
  font-weight: bold;
  margin-right: 10px;
}

