  font-size: 12px;
}

.empty {
  text-align: center;
  color: #999;
  padding: 40px 20px;
}

@media (max-width: 768px) {
  .summary {
    grid-template-columns: 1fr;
  }

  .form {
    grid-template-columns: 1fr;
  }
}
